inline std::string signedStr (int v) { return (v > 0 ? "+" : "") + std::to_string (v); }

inline std::string valueToText (const Param& p, int v)
{
    switch (p.disp)
    {
        case D::Num:        return std::to_string (v);
        case D::Bipolar99:  return signedStr (v - 99);
        case D::Fine50:     return signedStr (v - 50) + " ct";
        case D::OscShape:   return v == 0 ? "Saw" : v == 1 ? "Tri" : v == 2 ? "Saw/Tri" : "Pulse " + std::to_string (v - 3);
        case D::Wave:       return "Wave " + std::to_string (v + 1);
        case D::Glide:      return v <= 100 ? std::to_string (v) : v < 200 ? "Fing " + std::to_string (v - 100) : "Osc MIDI off";
        case D::LfoFreq:    return v <= 150 ? std::to_string (v) : lfoSyncs[v - 151];
        case D::LfoAmt:     return v <= 100 ? std::to_string (v) : "Key " + std::to_string (v - 100);
        case D::OnOff:      return v ? "On" : "Off";
        case D::KeyXpose:   return v == 0 ? "Off" : signedStr (v - 37);
        case D::OutIn:      return (v < 100 ? "Out " : "In ") + std::to_string (v % 100);
        case D::LfoShape:   return lfoShapes[v];
        case D::Pan:        return pans[v];
        case D::Trigger:    return triggers[v];
        case D::ExtInMode:  return extInModes[v];
        case D::KeyMode:    return keyModes[v];
        case D::ClockDiv:   return clockDivs[v];
        case D::ShapeMod:   return v == 0 ? "Off" : "Seq " + std::to_string (v);
        case D::Poles:      return v ? "4 pole" : "2 pole";
        case D::EnvShape:   return v ? "Linear" : "Exponential";
        case D::ModDest:
        case D::SeqDest:    return modDests[v];
        case D::ModSource:  return modSources[v];
    }
    return std::to_string (v);
}
